import react from "react";
import "../Styles/ItemPage.css"
import IconTeste from '../Images/Icons/DualSword.svg'
import SearchBar from "../Componentes/SearchBar";
import Item from "../Componentes/Item";
import Coin from '../Images/Icons/Coin.svg'
import Category from "../Images/Icons/Category.svg"
import all from "../Images/Icons/all.svg"
import shield from "../Images/Icons/Shield.svg"
import potion from "../Images/Icons/potion.svg"
import pentagram from "../Images/Icons/Pentagram.svg"
import star from "../Images/Icons/star.svg"
import { useState, useEffect } from "react";
import WindowEffect from "../Componentes/WindowEffect";
import bluestatic from "../Images/bluestatic.gif"

export default function ItemPage()
{

    const [ItemSelected, UseItemSelected] = useState(
        {"Nome": "[Selecione um item]",
        "Categoria": "",
        "Valor do item": "",
        "Arma": {},
        "Classe de armadura": "",
        "Descrição": "",
        "Categoria da Armadura": "",
        "Força": "",
        "Furtividade": ""}
    )

    const [newListItem, usenewListItem] = useState([])

      async function ChamarBanco(databaseName) {
          let Request = await fetch(`${process.env.PUBLIC_URL}/database/${databaseName}.json`).then(ResponseType => ResponseType.json())
          usenewListItem(Request)
          return Request
      }
    
      useEffect(()=>{
            ChamarBanco("Item")
      }, [])

    async function SelecionarItem(event) {
        
        const ItemClicked = event.target.id
        const AllItens = Array.from(document.getElementsByClassName("Item"))
        const ArmorInfo = document.getElementById("armorInfo")
        const WeaponInfo = document.getElementById("weaponInfo")
         let database = await ChamarBanco("Item")


        AllItens.map((data)=>{
            data.style.backgroundColor = "transparent"
        })

         event.target.style.backgroundColor = "#00d5ffad"
        
        database.map((data)=>{
            if(data.Nome == ItemClicked)
            {

                UseItemSelected(data)
                
                if(Object.keys(data.Arma).length == 0)
                {
                    WeaponInfo.style.display = "none"
                }
                else
                {
                    WeaponInfo.style.display = "block"
                }

                if(data["classe de armadura"] == "")
                {
                    ArmorInfo.style.display = "none"
                }
                else
                {
                    ArmorInfo.style.display = "flex"
                }
            }
        })

        console.log(ItemSelected)
    }

    async function FiltrarItem() {
        let database = await ChamarBanco("Item")
        const SearchBar = document.getElementById("SearchBar")
        const newList = []

        database.map((data)=>{
            if(data.Nome.toLowerCase().includes(SearchBar.value.toLowerCase()))
            {
                newList.push(data)
            }
        })

        usenewListItem(newList)
    }

    async function FiltrarCategoria(categoria)
    {
        const newList = []
        let database = await ChamarBanco("Item")

        database.map((data)=>{
           if(data.Categoria == categoria)
           {
                newList.push(data)
           }
        })

        console.log(newList)
        usenewListItem(newList)
    }

    return (
        <div className="ItemPage">
            <WindowEffect/>
            <div className="ItemCategory">
                <button onClick={()=>{FiltrarCategoria("geral")}}><img src={all}/></button>
                <button onClick={()=>{FiltrarCategoria("arma")}}><img src={IconTeste}/></button>
                <button onClick={()=>{FiltrarCategoria("armadura")}}><img src={shield}/></button>
                <button onClick={()=>{FiltrarCategoria("consumiveis")}}><img src={potion}/></button>
                <button onClick={()=>{FiltrarCategoria("itens magicos")}}><img src={pentagram}/></button>
                <button onClick={()=>{FiltrarCategoria("itens especiais")}}><img src={star}/></button>
            </div>
            <div className="Itens">
               <SearchBar changeEvent={()=>FiltrarItem()} width="99%"/>
                
                <div className="Itens-Container animate__animated animate__fadeIn">
                   {
                    newListItem.map((data)=>(
                        <Item click={(event)=>{SelecionarItem(event)}} Nome={data.Nome} Categoria={data.Categoria} Valor={data["Valor do item"]}/>
                    ))
                   }
                </div>
            </div>
            <div className="ItensInfo animate__animated animate__fadeIn" key={ItemSelected.Nome}>
                <div className="ItemInfo1">
                    <h1>{ItemSelected["Nome"]}</h1>
                    <div className="ItemDescription">
                        <img src={bluestatic}/>
                        <textarea readOnly style={ItemSelected["descrição"] != "" ? {} : {display:"flex",justifyContent:"center", textAlign: "center", alignContent: "center", verticalAlign: "middle"}} value={ItemSelected["descrição"] != "" ? ItemSelected["descrição"] : "[ITEM NÃO POSSUI DESCRIÇÃO]"}/>
                    </div>
                </div>
                <div className="ItemInfo2">
                    <h2><img src={Category}/>{"Categoria do item: " + ItemSelected["Categoria"]}</h2>
                    <h2><img src={Coin}/>{"Valor do item: " + ItemSelected["Valor do item"]}</h2>
                </div>
                <div className="ItemInfo3">
                    
                    <div className="weaponInfo" id="weaponInfo">
                        <div className="wpInfo2">
                            <h2>{"Propriedades: " + ItemSelected["Arma"]["Propriedades"]}</h2>
                        </div>
                        <div className="wpInfo1">
                            <h2>{"Bonus de Ataque: " + "+" + ItemSelected["Arma"]["Bônus de Ataque"]}</h2>
                            <h2>{"Dano da arma: " + ItemSelected["Arma"]["Dano da arma"]}</h2>
                        </div>
                    </div>

                    <div className="armorInfo" id="armorInfo">
                        <h2>{"Classe de Armadura: " + ItemSelected["Classe de armadura"]}</h2>
                    </div>
                </div>
                <button className="BuyItemButton">Comprar</button>
            </div>
        </div>
    )
}